local codec=require("lib.codec")local M={}local okSource,baked=pcall(require,"lib.runtime_source")if okSource and type(baked)=="string"then M.RUNTIME_SOURCE=baked end local function readFile(path)local f=assert(io.open(path,"rb"))local s=f:read("*a")f:close()return s end local runtimeSource local function runtime()if runtimeSource then return runtimeSource end local src=M.RUNTIME_SOURCE or readFile(M.runtimePath or"lib/runtime.lua")local out={}for line in(src.."\n"):gmatch("(.-)\n")do local trimmed=line:match("^%s*(.-)%s*$")if trimmed~=""and not trimmed:match("^%-%-")then out[#out+1]=trimmed end end runtimeSource=table.concat(out,"\n")return runtimeSource end local function bytes(s)local t={}for i=1,#s do t[i]=tostring(s:byte(i))end return"{"..table.concat(t,",").."}"end local function quote(s)return string.format("%q",s or""):gsub("\\\n","\\n")end function M.dataLiteral(data)local s={}for i,field in ipairs(data.s)do s[i]=quote(field)end local j={}for i,v in ipairs(data.j)do j[i]=tostring(v)end return"{k="..bytes(data.k)..",i="..bytes(data.i)..",a="..quote(data.a)..",s={"..table.concat(s,",").."},j={"..table.concat(j,",").."},u="..quote(data.u)..",v="..quote(data.v).."}"end function M.generate(cfg)local data=codec.encode(cfg)return table.concat({"-- brainCloud app config from the brainCloud setup tool. Regenerate, don't edit.",runtime(),"return install("..M.dataLiteral(data)..")","",},"\n")end function M.dataOf(source)local literal=source and source:match("\nreturn install%((%b{})%)%s*$")if not literal then return nil end local fn=loadstring("return "..literal)if not fn then return nil end setfenv(fn,{})local ok,data=pcall(fn)if not ok or type(data)~="table"then return nil end local function str(t)local out={}for i,b in ipairs(t)do out[i]=string.char(b)end return table.concat(out)end data.k=str(data.k)data.i=str(data.i)return data end return M
